{
  "name": "skillsmp-mcp",
  "version": "1.0.4",
  "description": "SkillsMP MCP Server - 为 OpenCode 集成 Skills Marketplace，提供关键字搜索和 AI 语义搜索功能",
  "main": "dist/index.js",
  "bin": {
    "skillsmp-mcp": "dist/index.js"
  },
  "type": "commonjs",
  "scripts": {
    "build": "tsc && sed -i.bak '1d' dist/index.js && (echo '#!/usr/bin/env node' && cat dist/index.js.bak) > dist/index.js.tmp && mv dist/index.js.tmp dist/index.js && rm dist/index.js.bak && chmod +x dist/index.js",
    "dev": "tsx src/index.ts",
    "test": "echo \"Error: no test specified\" && exit 1"
  },
  "keywords": [
    "skillsmp",
    "mcp",
    "model-context-protocol",
    "opencode",
    "search",
    "skills-marketplace",
    "ai-search",
    "semantic-search"
  ],
  "author": "fgallardo122",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/fgallardo122/skillsmp-mcp-server.git"
  },
  "bugs": {
    "url": "https://github.com/fgallardo122/skillsmp-mcp-server/issues"
  },
  "homepage": "https://github.com/fgallardo122/skillsmp-mcp-server#readme",
  "engines": {
    "node": ">=16.0.0"
  },
  "files": [
    "dist/index.js",
    "README.md",
    "LICENSE"
  ],
  "dependencies": {
    "@modelcontextprotocol/sdk": "^1.25.3"
  },
  "devDependencies": {
    "@types/node": "^25.0.10",
    "tsx": "^4.21.0",
    "typescript": "^5.9.3"
  }
}

#!/usr/bin/env node
"use strict";
Object.defineProperty(exports, "__esModule", { value: true });
const index_js_1 = require("@modelcontextprotocol/sdk/server/index.js");
const stdio_js_1 = require("@modelcontextprotocol/sdk/server/stdio.js");
const types_js_1 = require("@modelcontextprotocol/sdk/types.js");
// SkillsMP API 配置
// 使用环境变量 SKILLSMP_API_KEY 来提供密钥，避免将密钥硬编码到仓库中。
const SKILLSMP_API_KEY = process.env.SKILLSMP_API_KEY;
const SKILLSMP_API_BASE = "https://skillsmp.com/api/v1";
if (!SKILLSMP_API_KEY) {
    console.warn("Warning: SKILLSMP_API_KEY is not set. SkillsMP API calls will fail until you set the environment variable.");
}
// 工具定义
const SEARCH_TOOL = {
    name: "skillsmp_search",
    description: "使用关键字搜索 Skills Marketplace 中的技能。返回技能列表，包含名称、描述、作者、GitHub 链接等信息。",
    inputSchema: {
        type: "object",
        properties: {
            query: {
                type: "string",
                description: "搜索关键字（支持中文、英文）",
            },
            limit: {
                type: "number",
                description: "返回结果数量（默认 20，最大 100）",
                default: 20,
                maximum: 100,
            },
            sortBy: {
                type: "string",
                description: "排序方式：stars（按星数）或 recent（按最近更新）",
                enum: ["stars", "recent"],
                default: "recent",
            },
        },
        required: ["query"],
    },
};
const AI_SEARCH_TOOL = {
    name: "skillsmp_ai_search",
    description: "使用 AI 语义搜索 Skills Marketplace 中的技能。基于 Cloudflare AI 驱动，支持自然语言查询（如 \"How to create a web scraper\"）。",
    inputSchema: {
        type: "object",
        properties: {
            query: {
                type: "string",
                description: "自然语言查询（支持中文、英文）",
            },
            limit: {
                type: "number",
                description: "返回结果数量（默认 10）",
                default: 10,
            },
        },
        required: ["query"],
    },
};
// 调用 SkillsMP API
async function callSkillsMPAPI(endpoint, params) {
    const url = new URL(`${SKILLSMP_API_BASE}${endpoint}`);
    Object.entries(params).forEach(([key, value]) => {
        if (value !== undefined && value !== null) {
            url.searchParams.append(key, String(value));
        }
    });
    try {
        const response = await fetch(url.toString(), {
            method: "GET",
            headers: {
                "Authorization": `Bearer ${SKILLSMP_API_KEY}`,
                "Content-Type": "application/json",
            },
        });
        if (!response.ok) {
            const errorText = await response.text();
            throw new Error(`SkillsMP API error (${response.status}): ${errorText}`);
        }
        return await response.json();
    }
    catch (error) {
        console.error("Error calling SkillsMP API:", error);
        throw error;
    }
}
// 格式化技能列表
function formatSkills(data) {
    if (!data.success || !data.data || !data.data.skills) {
        return "搜索失败，请稍后重试。";
    }
    const { skills, pagination } = data.data;
    let result = `找到 ${pagination.total} 个相关技能（第 ${pagination.page} 页，显示 ${skills.length} 个）：\n\n`;
    skills.forEach((skill, index) => {
        result += `## ${index + 1}. ${skill.name}\n`;
        result += `- **作者**: ${skill.author}\n`;
        result += `- **描述**: ${skill.description}\n`;
        result += `- **星数**: ${skill.stars}\n`;
        result += `- **链接**: ${skill.skillUrl}\n`;
        result += `- **GitHub**: ${skill.githubUrl}\n\n`;
    });
    if (pagination.hasNext) {
        result += `\n还有更多结果，使用分页继续查询。`;
    }
    return result;
}
// 格式化 AI 搜索结果
function formatAISearchResults(data) {
    if (!data.success || !data.data || !data.data.data) {
        return "搜索失败，请稍后重试。";
    }
    const results = data.data.data;
    let result = `找到 ${results.length} 个相关技能（匹配度排序）：\n\n`;
    results.forEach((item, index) => {
        const skill = item.skill;
        result += `## ${index + 1}. ${skill.name} (相关度: ${(item.score * 100).toFixed(1)}%)\n`;
        result += `- **作者**: ${skill.author}\n`;
        result += `- **描述**: ${skill.description}\n`;
        result += `- **星数**: ${skill.stars}\n`;
        result += `- **链接**: ${skill.skillUrl}\n`;
        result += `- **GitHub**: ${skill.githubUrl}\n\n`;
    });
    return result;
}
// 创建服务器
const server = new index_js_1.Server({
    name: "skillsmp-mcp",
    version: "1.0.3",
}, {
    capabilities: {
        tools: {},
    },
});
// 处理工具列表请求
server.setRequestHandler(types_js_1.ListToolsRequestSchema, async () => {
    return {
        tools: [SEARCH_TOOL, AI_SEARCH_TOOL],
    };
});
// 处理工具调用请求
server.setRequestHandler(types_js_1.CallToolRequestSchema, async (request) => {
    const { name, arguments: args } = request.params;
    try {
        switch (name) {
            case "skillsmp_search": {
                const query = args?.query;
                const limit = args?.limit || 20;
                const sortBy = args?.sortBy || "recent";
                if (!query) {
                    throw new Error("缺少必需参数：query");
                }
                console.log(`Searching SkillsMP with query: ${query}, limit: ${limit}, sortBy: ${sortBy}`);
                const result = await callSkillsMPAPI("/skills/search", {
                    q: query,
                    limit,
                    sortBy,
                });
                return {
                    content: [
                        {
                            type: "text",
                            text: formatSkills(result),
                        },
                    ],
                };
            }
            case "skillsmp_ai_search": {
                const query = args?.query;
                const limit = args?.limit || 10;
                if (!query) {
                    throw new Error("缺少必需参数：query");
                }
                console.log(`AI Searching SkillsMP with query: ${query}, limit: ${limit}`);
                const result = await callSkillsMPAPI("/skills/ai-search", {
                    q: query,
                    limit,
                });
                return {
                    content: [
                        {
                            type: "text",
                            text: formatAISearchResults(result),
                        },
                    ],
                };
            }
            default:
                throw new Error(`未知的工具: ${name}`);
        }
    }
    catch (error) {
        const errorMessage = error instanceof Error ? error.message : String(error);
        console.error(`Error executing tool ${name}:`, errorMessage);
        return {
            content: [
                {
                    type: "text",
                    text: `工具执行失败: ${errorMessage}`,
                    isError: true,
                },
            ],
        };
    }
});
// 启动服务器
async function main() {
    const transport = new stdio_js_1.StdioServerTransport();
    await server.connect(transport);
    console.error("SkillsMP MCP Server running on stdio");
}
main().catch((error) => {
    console.error("Fatal error:", error);
    process.exit(1);
});
